// PawUI kit v1.1 - part of the paw-ui style library (generated by paw-ui/tools/scaffold.py).
using UnityEditor;
using UnityEngine;

namespace AutoSavePro.PawUI
{
    /// <summary>
    /// Data for PawGUI.NavTile. Keep one instance per tile and refresh its fields every OnGUI (Colors and
    /// Textures change when the skin/theme is rebuilt) - assigning fields allocates nothing.
    /// </summary>
    internal sealed class PawNavTile
    {
        internal Texture Glyph = null;
        internal Color Tint = default;
        /// <summary>Dim first line ("Build outputs").</summary>
        internal string Label = null;
        /// <summary>First line used when Sub doesn't fit next to the value ("Leftovers - can be freed"). Optional.</summary>
        internal string LabelWithSub = null;
        /// <summary>Bold second line ("186.0 MB").</summary>
        internal string Value = null;
        /// <summary>Dim text after the value ("3 builds"). Optional.</summary>
        internal string Sub = null;
        internal Color ValueColor = default;
        internal bool Strong = true;
        /// <summary>Small glyph before the value (e.g. a check for "Clean"). Optional.</summary>
        internal Texture ValueGlyph = null;
        internal string Tooltip = null;
        /// <summary>Inline button text ("Scan") - replaces the chevron. Optional.</summary>
        internal string ButtonText = null;
        internal bool ButtonEnabled = true;
        internal string ButtonTooltip = null;
        /// <summary>Read-only stat tile: no chevron, no hover, not clickable (a value to glance at).</summary>
        internal bool Static = false;
        /// <summary>Opens something outside the window (a URL, a file): an external-link glyph instead of the chevron.</summary>
        internal bool External = false;
    }

    internal static partial class PawGUI
    {
        // ---- Cards ------------------------------------------------------------------------------------
        /// <summary>
        /// Starts a card (vertical group with the card frame). Default padding 16/16/14/16; pass
        /// PawTheme.CompactCardPad / LogCardPad for dense cards. stretch = take the remaining page height (one per page).
        /// </summary>
        internal static Rect BeginCard(GUIStyle pad = null, bool stretch = false)
        {
            var r = stretch
                ? EditorGUILayout.BeginVertical(pad ?? PawTheme.CardPad, GUILayout.ExpandHeight(true))
                : EditorGUILayout.BeginVertical(pad ?? PawTheme.CardPad);
            CardFrame(r);
            return r;
        }

        internal static void EndCard() => EditorGUILayout.EndVertical();

        /// <summary>Icon tile + bold 13px title.</summary>
        internal static void CardHeader(Texture glyph, Color tint, string title)
        {
            BeginCardHeader(glyph, tint, title);
            EndCardHeader();
        }

        /// <summary>Icon tile + title + a dim right-aligned meta text ("Airi Custom - Today, 13:10").</summary>
        internal static void CardHeader(Texture glyph, Color tint, string title, string meta)
        {
            EditorGUILayout.BeginHorizontal();
            IconTile(glyph, tint);
            GUILayout.Space(10f);
            GUILayout.Label(title, PawTheme.Label(13, PawTheme.Text, true), GUILayout.Height(28f));
            var r = GUILayoutUtility.GetRect(10f, 28f, GUILayout.MinWidth(10f), GUILayout.ExpandWidth(true), GUILayout.Height(28f));
            if (IsRepaint && !string.IsNullOrEmpty(meta))
            {
                var style = PawTheme.Label(11, PawTheme.TextSecondary, anchor: TextAnchor.MiddleRight);
                GUI.Label(r, Ellipsize(meta, style, r.width - 8f), style);
            }
            EditorGUILayout.EndHorizontal();
        }

        /// <summary>Icon tile + title + a count chip on the right ("162 NAMES").</summary>
        internal static void CardHeader(Texture glyph, Color tint, string title, string chip, Color chipColor, string chipTooltip = null)
        {
            BeginCardHeader(glyph, tint, title);
            var cw = ChipWidth(chip);
            var r = GUILayoutUtility.GetRect(cw, 28f, GUILayout.Width(cw), GUILayout.Height(28f));
            Chip(new Rect(r.x, r.y + 4f, r.width, 20f), chip, chipColor);
            Tooltip(r, chipTooltip);
            EndCardHeader();
        }

        /// <summary>
        /// Icon tile + title, then a flexible space: add right-side controls (LayoutButton with height 28) and call
        /// EndCardHeader.
        /// </summary>
        internal static void BeginCardHeader(Texture glyph, Color tint, string title)
        {
            EditorGUILayout.BeginHorizontal();
            IconTile(glyph, tint);
            GUILayout.Space(10f);
            GUILayout.Label(title, PawTheme.Label(13, PawTheme.Text, true), GUILayout.Height(28f), GUILayout.MinWidth(40f));
            GUILayout.FlexibleSpace();
        }

        internal static void EndCardHeader() => EditorGUILayout.EndHorizontal();

        /// <summary>
        /// Collapsible card header (the EditorGUILayout.Foldout replacement): icon tile + title + dim meta + chevron, the
        /// whole row toggles. Returns the new open state; draw the body only when open:
        ///   PawGUI.BeginCard(); _open = PawGUI.FoldoutHeader(_open, glyph, tint, "Advanced", "3 options");
        ///   if (_open) { PawGUI.CardText(...); ... } PawGUI.EndCard();
        /// Keep the open flag in a [SerializeField] so it survives domain reloads.
        /// </summary>
        internal static bool FoldoutHeader(bool open, Texture glyph, Color tint, string title, string meta = null, string tooltip = null)
        {
            var r = GUILayoutUtility.GetRect(0f, 28f, GUILayout.ExpandWidth(true), GUILayout.Height(28f));
            var hit = new Rect(r.x - 6f, r.y - 4f, r.width + 12f, r.height + 8f);
            var clicked = Click(hit, true, title, out var hover, out _);
            if (IsRepaint)
            {
                if (hover) Fill(hit, PawTheme.Alpha(PawTheme.SurfaceHover, 0.7f), ControlRadius);
                IconTile(new Rect(r.x, r.y, 28f, 28f), glyph, tint);
                var x = r.x + 38f;
                var chevron = new Rect(r.xMax - 18f, Mathf.Round(r.center.y - 7f), 14f, 14f);
                var titleStyle = PawTheme.Label(13, PawTheme.Text, true);
                var shown = Ellipsize(title, titleStyle, Mathf.Max(0f, chevron.x - 8f - x));
                var tw = Measure(shown, titleStyle).x;
                GUI.Label(new Rect(x, r.y, tw + 2f, r.height), shown, titleStyle);
                if (!string.IsNullOrEmpty(meta))
                {
                    var metaStyle = PawTheme.Label(11, PawTheme.TextSecondary, anchor: TextAnchor.MiddleRight);
                    var mx = x + tw + 12f;
                    var mw = Mathf.Max(0f, chevron.x - 10f - mx);
                    GUI.Label(new Rect(mx, r.y, mw, r.height), Ellipsize(meta, metaStyle, mw), metaStyle);
                }
                Glyph(chevron, open ? PawGlyphs.ChevronDown : PawGlyphs.Chevron, hover ? PawTheme.Text : PawTheme.TextMuted);
            }
            Tooltip(hit, tooltip ?? (open ? "Click to collapse" : "Click to expand"));
            if (!clicked) return open;
            GUI.changed = true;
            return !open;
        }

        /// <summary>
        /// The one headline figure of a card: a 22px bold value with a dim caption on its baseline ("03:12  until the next
        /// save", "186 MB  can be freed"). valueWidth &gt; 0 keeps a ticking value from jittering the caption.
        /// </summary>
        internal static void Metric(string value, string caption, Color color = default, float valueWidth = 0f)
        {
            var valueStyle = PawTheme.Label(22, color.a > 0f ? color : PawTheme.Text, true);
            var w = valueWidth > 0f ? valueWidth : Mathf.Ceil(Measure(value, valueStyle).x) + 2f;
            EditorGUILayout.BeginHorizontal();
            GUILayout.Label(value, valueStyle, GUILayout.Width(w), GUILayout.Height(30f));
            if (!string.IsNullOrEmpty(caption))
            {
                GUILayout.Space(6f);
                var r = GUILayoutUtility.GetRect(20f, 30f, GUILayout.MinWidth(20f), GUILayout.ExpandWidth(true), GUILayout.Height(30f));
                if (IsRepaint)
                {
                    var style = PawTheme.Label(11, PawTheme.TextSecondary);
                    GUI.Label(new Rect(r.x, r.y + 11f, r.width, 16f), Ellipsize(caption, style, r.width), style);
                }
            }
            EditorGUILayout.EndHorizontal();
        }

        /// <summary>11px secondary wrapped text under a header (rich = allow &lt;b&gt;).</summary>
        internal static void CardText(string text, bool rich = false, float spaceAbove = 6f)
